#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""W009 dot3: run the fixed-seed proof set on both arms and compare.
Usage: run_diff.py <dot3-diff dir> <shards>
Arm A (patched multiexp) first; then arm P (pristine 0.5.2) with DOT3_XDIR=A's proofs, so the
pristine build verifies every proof the patched build made; then a repeat of a subset of P
(P2) to show the harness is deterministic. Writes cases.txt, logs and summary.txt."""
import glob, hashlib, os, subprocess, sys, time

base, shards = sys.argv[1], int(sys.argv[2])

cases = []
for n in (1, 2, 3, 4, 5):
    for layers in range(1, 9):
        for seed in (1, 2, 3, 4):
            cases.append((n, layers, seed, 0))
for n in (8, 13, 18):
    for layers in range(1, 9):
        for seed in (1, 2):
            cases.append((n, layers, seed, 0))
for n in (2, 7, 18):
    for layers in (2, 3, 5):
        for seed in (1, 2):
            cases.append((n, layers, seed, 1))
for n in (19, 32, 64):
    for layers in (3, 4, 6, 8):
        for seed in (1, 2):
            cases.append((n, layers, seed, 1))
for layers in (3, 4, 7, 8):
    for seed in (1, 2):
        cases.append((128, layers, seed, 1))

def name(c):
    return "%d_%d_%d_%d" % c

def cost(c):
    return c[0] * (c[1] + 2)

with open(os.path.join(base, "cases.txt"), "w") as f:
    for c in cases:
        f.write(name(c) + "\n")

def split(cs, k):
    bins = [[] for _ in range(k)]
    load = [0] * k
    for c in sorted(cs, key=cost, reverse=True):
        i = load.index(min(load))
        bins[i].append(c)
        load[i] += cost(c)
    return [b for b in bins if b]

def binary(arm):
    exe = [p for p in glob.glob(os.path.join(base, "target-%s/release/deps/full_chain_membership_proofs-*" % arm))
           if os.access(p, os.X_OK) and not p.endswith(".d")]
    assert len(exe) == 1, exe
    return exe[0]

def run_arm(arm, out, cs, xdir=None):
    os.makedirs(out, exist_ok=True)
    exe = binary(arm)
    procs = []
    for i, b in enumerate(split(cs, shards)):
        env = dict(os.environ, DOT3_OUT=out, DOT3_MAX_INPUTS="128",
                   DOT3_CASES=",".join("%d:%d:%d:%d" % c for c in b))
        if xdir:
            env["DOT3_XDIR"] = xdir
        log = open(os.path.join(out, "shard%02d.log" % i), "w")
        procs.append(subprocess.Popen([exe, "--ignored", "--exact", "tests::dot3_diff::dot3_diff",
                                       "--test-threads=1", "--nocapture"],
                                      env=env, stdout=log, stderr=subprocess.STDOUT))
    rcs = [p.wait() for p in procs]
    return rcs

def sha(path):
    return hashlib.sha256(open(path, "rb").read()).hexdigest()

summary = open(os.path.join(base, "summary.txt"), "w")
def say(s):
    print(s, flush=True)
    summary.write(s + "\n")
    summary.flush()

say("cases: %d (inputs 1-128, layers 1-8), shards: %d" % (len(cases), shards))
t = time.time()
rc = run_arm("A", os.path.join(base, "out-A"), cases)
say("arm A (patched): shard rcs %s, %.0f s" % (rc, time.time() - t))
t = time.time()
rc = run_arm("P", os.path.join(base, "out-P"), cases, xdir=os.path.join(base, "out-A"))
say("arm P (pristine, verifies A's proofs): shard rcs %s, %.0f s" % (rc, time.time() - t))
subset = [c for c in cases if c[0] <= 5 and c[2] == 1] + [c for c in cases if c[3] == 1 and c[2] == 1 and c[0] in (18, 32)]
t = time.time()
rc = run_arm("P", os.path.join(base, "out-P2"), subset)
say("arm P repeat (determinism), %d cases: shard rcs %s, %.0f s" % (len(subset), rc, time.time() - t))

same = differ = missing = 0
for c in cases:
    a, p = os.path.join(base, "out-A", name(c) + ".bin"), os.path.join(base, "out-P", name(c) + ".bin")
    if not (os.path.exists(a) and os.path.exists(p)):
        missing += 1
        say("MISSING " + name(c))
    elif sha(a) == sha(p):
        same += 1
    else:
        differ += 1
        say("DIFFER " + name(c))
rep_same = sum(1 for c in subset if os.path.exists(os.path.join(base, "out-P2", name(c) + ".bin")) and
               sha(os.path.join(base, "out-P2", name(c) + ".bin")) == sha(os.path.join(base, "out-P", name(c) + ".bin")))
lines = []
for f in glob.glob(os.path.join(base, "out-P", "shard*.log")):
    lines += [l for l in open(f) if l.startswith("DOT3CASE")]
cross_ok = sum(1 for l in lines if "cross=same-and-verified" in l)
say("byte-identical A vs P: %d of %d (differ %d, missing %d)" % (same, len(cases), differ, missing))
say("P's verifier accepted A's proof (cross=same-and-verified): %d of %d" % (cross_ok, len(cases)))
say("determinism, P repeat identical to P: %d of %d" % (rep_same, len(subset)))
with open(os.path.join(base, "sha256s.txt"), "w") as f:
    for c in cases:
        p = os.path.join(base, "out-A", name(c) + ".bin")
        if os.path.exists(p):
            f.write("%s  %s\n" % (sha(p), name(c)))
say("done")
